/* eslint-disable @typescript-eslint/no-explicit-any */
import { FormEvent, useEffect, useMemo, useState } from 'react';
import { BrowserRouter, Link, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { ArrowRight, BarChart3, Check, ChevronDown, Heart, LogIn, LogOut, Menu, Package, Search, ShoppingBag, Sparkles, Star, TrendingUp, User, Zap } from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { getRecommendations, getTrending, INTERACTION_WEIGHTS, type RecommendedProduct } from '@/lib/recommendations';

type Product = { id: string; name: string; description: string; price: number; discount: number; brand: string; image_url: string; stock: number; rating: number; review_count: number; tags: string[]; category_id: string; created_at?: string; category?: { name: string; slug: string } };
type Category = { id: string; name: string; slug: string; description: string; image_url: string };
type CartItem = { id: string; product_id: string; quantity: number; product: Product };

const money = (value: number) => `${value.toFixed(2)}`;
const salePrice = (p: Product) => p.price * (1 - p.discount / 100);

function App() {
  return <BrowserRouter><Storefront /></BrowserRouter>;
}

function Storefront() {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [cartCount, setCartCount] = useState(0);
  const [wishCount, setWishCount] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);

  const refreshCounts = async (id?: string) => {
    if (!id) { setCartCount(0); setWishCount(0); return; }
    const [{ count: cart }, { count: wish }] = await Promise.all([
      supabase.from('cart_items').select('*', { count: 'exact', head: true }).eq('user_id', id),
      supabase.from('wishlist_items').select('*', { count: 'exact', head: true }).eq('user_id', id),
    ]);
    setCartCount(cart ?? 0); setWishCount(wish ?? 0);
  };
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => { setUser(data.session?.user ?? null); if (data.session?.user) loadProfile(data.session.user.id); });
    const { data } = supabase.auth.onAuthStateChange((_event, session) => { setUser(session?.user ?? null); refreshCounts(session?.user?.id); if (session?.user) loadProfile(session.user.id); });
    return () => data.subscription.unsubscribe();
  }, []);
  const loadProfile = async (id: string) => { const { data } = await supabase.from('profiles').select('*').eq('id', id).maybeSingle(); setProfile(data); refreshCounts(id); };
  const logout = async () => { await supabase.auth.signOut(); setProfile(null); };
  return <div className="min-h-screen bg-[#f8fafc] text-slate-900">
    <header className="sticky top-0 z-40 border-b border-slate-200/80 bg-white/90 backdrop-blur-xl">
      <div className="mx-auto flex h-20 max-w-7xl items-center gap-6 px-4 lg:px-8">
        <button className="rounded-lg p-2 lg:hidden" onClick={() => setMenuOpen(!menuOpen)}><Menu size={22}/></button>
        <Link to="/" className="flex items-center gap-2 text-xl font-bold tracking-tight"><span className="grid h-9 w-9 place-items-center rounded-xl bg-slate-950 text-white"><Sparkles size={18}/></span>luma<span className="text-emerald-500">market</span></Link>
        <nav className={`${menuOpen ? 'absolute left-0 right-0 top-20 flex bg-white p-5 shadow-xl' : 'hidden'} flex-col gap-4 text-sm font-medium lg:static lg:flex lg:flex-row lg:bg-transparent lg:p-0 lg:shadow-none`}>
          <Link onClick={() => setMenuOpen(false)} to="/">Home</Link><Link onClick={() => setMenuOpen(false)} to="/products">Shop</Link><Link onClick={() => setMenuOpen(false)} to="/categories">Categories</Link><Link onClick={() => setMenuOpen(false)} to="/recommendations">For you</Link>
        </nav>
        <div className="ml-auto hidden max-w-md flex-1 lg:block"><SearchBox /></div>
        <div className="flex items-center gap-1">
          {user && <Link className="relative rounded-xl p-2 hover:bg-slate-100" to="/wishlist"><Heart size={20}/>{wishCount > 0 && <Badge>{wishCount}</Badge>}</Link>}
          <Link className="relative rounded-xl p-2 hover:bg-slate-100" to="/cart"><ShoppingBag size={20}/>{cartCount > 0 && <Badge>{cartCount}</Badge>}</Link>
          {user ? <div className="group relative"><button className="ml-1 flex items-center gap-2 rounded-xl p-2 hover:bg-slate-100"><span className="grid h-8 w-8 place-items-center rounded-full bg-emerald-100 text-sm font-bold text-emerald-700">{(profile?.name ?? user.email ?? 'U')[0].toUpperCase()}</span><ChevronDown size={15}/></button><div className="invisible absolute right-0 top-12 w-48 rounded-2xl border border-slate-100 bg-white p-2 opacity-0 shadow-xl transition group-hover:visible group-hover:opacity-100"><p className="px-3 py-2 text-xs text-slate-500">{profile?.name ?? user.email}</p><Link className="block rounded-xl px-3 py-2 text-sm hover:bg-slate-50" to="/account">My account</Link>{profile?.role === 'ADMIN' && <Link className="block rounded-xl px-3 py-2 text-sm hover:bg-slate-50" to="/admin">Admin studio</Link>}<button onClick={logout} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left text-sm text-rose-600 hover:bg-rose-50"><LogOut size={15}/>Sign out</button></div></div> : <Link to="/login" className="ml-2 hidden items-center gap-2 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white sm:flex"><LogIn size={15}/>Sign in</Link>}
        </div>
      </div>
      <div className="px-4 pb-3 lg:hidden"><SearchBox /></div>
    </header>
    <Routes><Route path="/" element={<HomePage/>}/><Route path="/products" element={<ProductsPage/>}/><Route path="/product/:id" element={<ProductPage user={user} refreshCounts={() => refreshCounts(user?.id)}/>}/><Route path="/categories" element={<CategoriesPage/>}/><Route path="/recommendations" element={<RecommendationsPage user={user}/>}/><Route path="/about" element={<AboutPage/>}/><Route path="/contact" element={<ContactPage/>}/><Route path="/forgot-password" element={<ForgotPasswordPage/>}/><Route path="/wishlist" element={<WishlistPage user={user}/>}/><Route path="/cart" element={<CartPage user={user}/>}/><Route path="/checkout" element={<CheckoutPage user={user} refreshCounts={() => refreshCounts(user?.id)}/>}/><Route path="/account" element={<AccountPage user={user}/>}/><Route path="/orders" element={<OrdersPage user={user}/>}/><Route path="/orders/:id" element={<OrderDetailsPage user={user}/>}/><Route path="/admin" element={<AdminPage profile={profile}/>}/><Route path="/admin/products" element={<AdminProductsPage profile={profile}/>}/><Route path="/admin/products/add" element={<AdminProductFormPage profile={profile}/>}/><Route path="/admin/products/:id/edit" element={<AdminProductFormPage profile={profile}/>}/><Route path="/admin/users" element={<AdminUsersPage profile={profile}/>}/><Route path="/admin/orders" element={<AdminOrdersPage profile={profile}/>}/><Route path="/admin/analytics" element={<AdminAnalyticsPage profile={profile}/>}/><Route path="/login" element={<AuthPage mode="login"/>}/><Route path="/register" element={<AuthPage mode="register"/>}/><Route path="/admin" element={<AdminPage profile={profile}/>}/><Route path="*" element={<HomePage/>}/></Routes>
    <footer className="mt-24 border-t border-slate-200 bg-white"><div className="mx-auto flex max-w-7xl flex-col gap-6 px-4 py-10 text-sm text-slate-500 sm:flex-row sm:items-center sm:justify-between lg:px-8"><div><p className="font-semibold text-slate-900">luma<span className="text-emerald-500">market</span></p><p className="mt-1">A smarter way to discover your next favorite.</p></div><div className="flex gap-5"><Link to="/products">Shop all</Link><Link to="/recommendations">Recommendations</Link><Link to="/categories">Categories</Link><Link to="/about">About</Link><Link to="/contact">Contact</Link></div></div></footer>
  </div>;
}
function Badge({ children }: { children: number }) { return <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-emerald-500 px-1 text-[10px] font-bold text-white">{children}</span>; }
function SearchBox() { const [q, setQ] = useState(''); const nav = useNavigate(); return <form onSubmit={(e) => { e.preventDefault(); nav(`/products?search=${encodeURIComponent(q)}`); }} className="flex items-center gap-2 rounded-xl bg-slate-100 px-3 py-2.5"><Search size={17} className="text-slate-400"/><input value={q} onChange={e => setQ(e.target.value)} placeholder="Search products, brands, and more" className="w-full bg-transparent text-sm outline-none placeholder:text-slate-400"/></form>; }
function Shell({ eyebrow, title, subtitle, children }: { eyebrow?: string; title: string; subtitle?: string; children: React.ReactNode }) { return <main className="mx-auto max-w-7xl px-4 py-10 lg:px-8"><div className="mb-8"><p className="mb-2 text-xs font-bold uppercase tracking-[.2em] text-emerald-600">{eyebrow}</p><h1 className="text-3xl font-bold tracking-tight sm:text-4xl">{title}</h1>{subtitle && <p className="mt-2 max-w-2xl text-slate-500">{subtitle}</p>}</div>{children}</main>; }
function HomePage() { const [products, setProducts] = useState<Product[]>([]); const [cats, setCats] = useState<Category[]>([]); useEffect(() => { Promise.all([supabase.from('products').select('*, category:categories(name,slug)').order('rating',{ascending:false}).limit(8), supabase.from('categories').select('*').limit(7)]).then(([p,c]) => { setProducts((p.data ?? []) as Product[]); setCats(c.data ?? []); }); }, []); return <main><section className="relative overflow-hidden bg-slate-950"><div className="absolute inset-0 bg-[radial-gradient(circle_at_80%_20%,rgba(16,185,129,.24),transparent_35%)]"/><div className="relative mx-auto grid max-w-7xl gap-10 px-4 py-20 lg:grid-cols-[1.1fr_.9fr] lg:items-center lg:px-8 lg:py-28"><div><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-emerald-400/30 bg-emerald-400/10 px-3 py-1.5 text-xs font-semibold text-emerald-300"><Zap size={14}/> Curated for curious shoppers</div><h1 className="max-w-2xl text-5xl font-bold leading-[1.05] tracking-tight text-white sm:text-6xl">Discover products <span className="text-emerald-400">you'll love.</span></h1><p className="mt-6 max-w-xl text-lg leading-8 text-slate-300">A thoughtful shopping experience that learns what makes you tick, then surfaces the things worth your attention.</p><div className="mt-8 flex flex-wrap gap-3"><Link to="/products" className="inline-flex items-center gap-2 rounded-xl bg-emerald-400 px-5 py-3.5 font-semibold text-slate-950 transition hover:bg-emerald-300">Shop now <ArrowRight size={17}/></Link><Link to="/recommendations" className="rounded-xl border border-white/20 px-5 py-3.5 font-semibold text-white transition hover:bg-white/10">Explore for you</Link></div></div><div className="grid grid-cols-2 gap-4"><div className="translate-y-8 rounded-3xl bg-white/10 p-3 backdrop-blur"><img className="aspect-square w-full rounded-2xl object-cover" src={products[0]?.image_url} alt=""/><p className="p-3 text-sm font-semibold text-white">Curated essentials</p></div><div className="rounded-3xl bg-emerald-400 p-3"><div className="flex aspect-square flex-col justify-between rounded-2xl bg-slate-900 p-5 text-white"><Sparkles className="text-emerald-400"/><div><p className="text-3xl font-bold">40+</p><p className="mt-1 text-sm text-slate-300">ways we personalize your feed</p></div></div><p className="p-3 text-sm font-semibold text-slate-950">Made for your rhythm</p></div></div></div></section><Shell eyebrow="Explore" title="Shop by mood"><div className="grid grid-cols-2 gap-4 sm:grid-cols-4 lg:grid-cols-7">{cats.map(c => <Link to={`/products?category=${c.slug}`} key={c.id} className="group overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-100"><img src={c.image_url} alt="" className="aspect-square w-full object-cover transition duration-500 group-hover:scale-105"/><p className="p-3 text-sm font-semibold">{c.name}</p></Link>)}</div></Shell><Shell eyebrow="Trending now" title="Popular with the community" subtitle="Loved, saved, and added to carts this week."><ProductGrid products={products.slice(0,4)}/></Shell></main>; }
function ProductsPage() { const [products,setProducts] = useState<Product[]>([]); const [categories,setCategories] = useState<Category[]>([]); const [params] = useSearchParams(); const [sort,setSort] = useState('rating'); const [category,setCategory] = useState(params.get('category') ?? ''); const search = params.get('search') ?? ''; useEffect(() => { supabase.from('products').select('*, category:categories(name,slug)').then(({data}) => setProducts((data ?? []) as Product[])); supabase.from('categories').select('*').then(({data}) => setCategories(data ?? [])); }, []); const filtered = useMemo(() => { const list=products.filter(p => (!search || p.name.toLowerCase().includes(search.toLowerCase()) || p.brand.toLowerCase().includes(search.toLowerCase())) && (!category || p.category?.slug===category)); return [...list].sort((a,b) => sort==='price-low' ? salePrice(a)-salePrice(b) : sort==='price-high' ? salePrice(b)-salePrice(a) : sort==='newest' ? +new Date(b.created_at as any)-+new Date(a.created_at as any) : b.rating-a.rating); }, [products,search,category,sort]); return <Shell eyebrow={search ? 'Search results' : 'The collection'} title={search ? `Results for “${search}”` : 'Find your next favorite'} subtitle="Browse our considered collection of products selected for quality, usefulness, and a little delight."><div className="mb-7 flex flex-wrap gap-3"><select value={category} onChange={e=>setCategory(e.target.value)} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"><option value="">All categories</option>{categories.map(c=><option value={c.slug} key={c.id}>{c.name}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)} className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"><option value="rating">Top rated</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="newest">Newest</option></select><span className="ml-auto self-center text-sm text-slate-500">{filtered.length} products</span></div>{filtered.length ? <ProductGrid products={filtered}/> : <Empty title="No products found" text="Try adjusting your search or filters."/>}</Shell>; }
function ProductGrid({ products }: { products: Product[] }) { return <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">{products.map(p=><ProductCard key={p.id} product={p}/>)}</div>; }
function ProductCard({ product }: { product: Product }) { const [busy,setBusy]=useState(false); const add = async () => { const {data:{user}}=await supabase.auth.getUser(); if(!user){ alert('Please sign in to add items.'); return; } setBusy(true); await supabase.from('cart_items').upsert({user_id:user.id,product_id:product.id,quantity:1},{onConflict:'user_id,product_id'}); await supabase.from('user_interactions').insert({user_id:user.id,product_id:product.id,interaction_type:'CART',weight:3}); setBusy(false); }; return <article className="group relative overflow-hidden rounded-2xl bg-white ring-1 ring-slate-100 transition hover:-translate-y-1 hover:shadow-xl"><Link to={`/product/${product.id}`}><div className="relative overflow-hidden bg-slate-100"><img loading="lazy" className="aspect-square w-full object-cover transition duration-500 group-hover:scale-105" src={product.image_url} alt={product.name}/>{product.discount > 0 && <span className="absolute left-3 top-3 rounded-full bg-emerald-500 px-2 py-1 text-[10px] font-bold text-white">-{product.discount}%</span>}</div><div className="p-4"><p className="text-xs text-slate-400">{product.brand}</p><h3 className="mt-1 line-clamp-1 font-semibold">{product.name}</h3><div className="mt-2 flex items-center gap-1 text-xs text-amber-500"><Star size={13} fill="currentColor"/>{product.rating.toFixed(1)} <span className="text-slate-400">({product.review_count})</span></div><div className="mt-3 flex items-center gap-2"><span className="font-bold">{money(salePrice(product))}</span>{product.discount > 0 && <del className="text-xs text-slate-400">{money(product.price)}</del>}</div></div></Link><button disabled={busy} onClick={add} className="absolute bottom-3 right-3 grid h-9 w-9 place-items-center rounded-xl bg-slate-950 text-white opacity-0 transition group-hover:opacity-100 hover:bg-emerald-500"><ShoppingBag size={16}/></button></article>; }
function ProductPage({ user, refreshCounts }: { user:any; refreshCounts:()=>void }) { const {id}=useParams(); const [product,setProduct]=useState<Product|null>(null); const [reviews,setReviews]=useState<any[]>([]); const [qty,setQty]=useState(1); const [review,setReview]=useState(''); const [rating,setRating]=useState(5); useEffect(()=>{ if(!id)return; supabase.from('products').select('*, category:categories(name,slug)').eq('id',id).maybeSingle().then(({data})=>setProduct(data as Product)); supabase.from('reviews').select('*, profile:profiles(name)').eq('product_id',id).order('created_at',{ascending:false}).then(({data})=>setReviews(data??[])); supabase.auth.getUser().then(({data:{user}})=>{if(user)supabase.from('user_interactions').insert({user_id:user.id,product_id:id,interaction_type:'VIEW',weight:1});}); },[id]); if(!product)return <Shell title="Loading product..."><div className="h-96 animate-pulse rounded-3xl bg-slate-200"/></Shell>; const addCart=async()=>{if(!user){alert('Please sign in first.');return;} await supabase.from('cart_items').upsert({user_id:user.id,product_id:product.id,quantity:qty},{onConflict:'user_id,product_id'}); await supabase.from('user_interactions').insert({user_id:user.id,product_id:product.id,interaction_type:'CART',weight:3}); refreshCounts(); alert('Added to your bag.');}; const wishlist=async()=>{if(!user){alert('Please sign in first.');return;} await supabase.from('wishlist_items').upsert({user_id:user.id,product_id:product.id},{onConflict:'user_id,product_id'}); await supabase.from('user_interactions').insert({user_id:user.id,product_id:product.id,interaction_type:'WISHLIST',weight:4}); refreshCounts(); alert('Saved to wishlist.');}; const submitReview=async(e:FormEvent)=>{e.preventDefault();if(!user)return alert('Please sign in to review.');await supabase.from('reviews').upsert({user_id:user.id,product_id:product.id,rating,comment:review},{onConflict:'user_id,product_id'});await supabase.from('user_interactions').insert({user_id:user.id,product_id:product.id,interaction_type:'RATING',weight:3});setReview('');alert('Review saved.');}; return <Shell eyebrow={product.category?.name} title={product.name}><div className="grid gap-10 lg:grid-cols-2"><div className="overflow-hidden rounded-3xl bg-white p-4 ring-1 ring-slate-100"><img className="aspect-square w-full rounded-2xl object-cover" src={product.image_url} alt={product.name}/></div><div className="py-4"><p className="font-medium text-emerald-600">{product.brand}</p><div className="mt-3 flex items-center gap-2 text-sm text-amber-500"><Star fill="currentColor" size={17}/>{product.rating.toFixed(1)} <span className="text-slate-400">from {product.review_count} reviews</span></div><p className="mt-6 text-4xl font-bold">{money(salePrice(product))}</p>{product.discount>0&&<p className="mt-2 text-sm text-slate-400"><del>{money(product.price)}</del> <span className="font-semibold text-emerald-600">Save {product.discount}%</span></p>}<p className="mt-6 leading-7 text-slate-600">{product.description}</p><p className="mt-5 text-sm font-medium text-emerald-600">{product.stock > 0 ? `${product.stock} in stock` : 'Out of stock'}</p><div className="mt-7 flex flex-wrap gap-3"><div className="flex items-center rounded-xl border border-slate-200"><button onClick={()=>setQty(Math.max(1,qty-1))} className="px-4 py-3">−</button><span className="w-8 text-center">{qty}</span><button onClick={()=>setQty(Math.min(product.stock,qty+1))} className="px-4 py-3">+</button></div><button onClick={addCart} className="flex-1 rounded-xl bg-slate-950 px-5 py-3 font-semibold text-white hover:bg-emerald-500">Add to bag</button><button onClick={wishlist} className="rounded-xl border border-slate-200 px-4 hover:border-rose-300 hover:text-rose-500"><Heart size={20}/></button></div></div></div><div className="mt-14 grid gap-10 lg:grid-cols-[1fr_360px]"><section><h2 className="text-2xl font-bold">Customer reviews</h2><div className="mt-5 space-y-4">{reviews.length?reviews.map(r=><div className="rounded-2xl bg-white p-5 ring-1 ring-slate-100" key={r.id}><div className="flex justify-between"><p className="font-semibold">{r.profile?.name ?? 'Customer'}</p><div className="flex text-amber-500">{[1,2,3,4,5].map(n=><Star key={n} size={14} fill={n<=r.rating?'currentColor':'none'}/>)}</div></div><p className="mt-3 text-sm leading-6 text-slate-600">{r.comment}</p></div>):<Empty title="No reviews yet" text="Be the first to share your thoughts."/>}</div></section><form onSubmit={submitReview} className="h-fit rounded-2xl bg-white p-6 ring-1 ring-slate-100"><h3 className="font-bold">Share your experience</h3><div className="mt-4 flex gap-1">{[1,2,3,4,5].map(n=><button type="button" key={n} onClick={()=>setRating(n)} className={n<=rating?'text-amber-500':'text-slate-300'}><Star fill="currentColor"/></button>)}</div><textarea value={review} onChange={e=>setReview(e.target.value)} required placeholder="What did you think?" className="mt-4 h-28 w-full resize-none rounded-xl border border-slate-200 p-3 text-sm outline-none focus:border-emerald-500"/><button className="mt-3 w-full rounded-xl bg-slate-950 py-3 font-semibold text-white">Post review</button></form></div></Shell>; }
function CategoriesPage(){const [cats,setCats]=useState<Category[]>([]);useEffect(()=>{supabase.from('categories').select('*').then(({data})=>setCats(data??[]))},[]);return <Shell eyebrow="Explore" title="Choose your corner of the market" subtitle="Start with a category, then let the details guide you."><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{cats.map(c=><Link key={c.id} to={`/products?category=${c.slug}`} className="group relative overflow-hidden rounded-3xl bg-slate-950"><img src={c.image_url} alt="" className="aspect-[1.3] w-full object-cover opacity-70 transition duration-500 group-hover:scale-105 group-hover:opacity-50"/><div className="absolute inset-0 flex flex-col justify-end bg-gradient-to-t from-slate-950/80 p-6 text-white"><h2 className="text-xl font-bold">{c.name}</h2><p className="mt-1 text-sm text-slate-300">{c.description}</p></div></Link>)}</div></Shell>}

function RecommendationsPage({user}:{user:any}){const [products,setProducts]=useState<RecommendedProduct[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{(async()=>{setLoading(true);if(user){setProducts(await getRecommendations(user.id,8));}else{const t=await getTrending(8);setProducts(t.map(p=>({...p,recommendationScore:0,recommendationReason:'Trending now'})));}setLoading(false);})()},[user]);return <Shell eyebrow="Your personal edit" title={user?'Recommended for you':'Trending picks'} subtitle={user?'Based on your browsing, saves, cart activity, and ratings.':'Sign in to unlock recommendations tuned to your taste.'}><div className="mb-8 flex items-center gap-3 rounded-2xl bg-emerald-50 p-4 text-sm text-emerald-900"><Sparkles size={20}/><span>{user?'Your feed updates as you shop. Every view and save helps us understand your style.':'These are our community favorites. Create an account to make them yours.'}</span></div>{loading?<div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">{Array.from({length:8}).map((_,i)=><div key={i} className="h-72 animate-pulse rounded-2xl bg-slate-200"/>)}</div>:<div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">{products.map(p=><div key={p.id} className="group relative overflow-hidden rounded-2xl bg-white ring-1 ring-slate-100 transition hover:-translate-y-1 hover:shadow-xl"><Link to={`/product/${p.id}`}><div className="relative overflow-hidden bg-slate-100"><img loading="lazy" className="aspect-square w-full object-cover transition duration-500 group-hover:scale-105" src={p.image_url} alt={p.name}/>{p.discount > 0 && <span className="absolute left-3 top-3 rounded-full bg-emerald-500 px-2 py-1 text-[10px] font-bold text-white">-{p.discount}%</span>}</div><div className="p-4"><span className="inline-block rounded-full bg-emerald-50 px-2 py-0.5 text-[10px] font-semibold text-emerald-700">{p.recommendationReason}</span><p className="mt-2 text-xs text-slate-400">{p.brand}</p><h3 className="mt-1 line-clamp-1 font-semibold">{p.name}</h3><div className="mt-2 flex items-center gap-1 text-xs text-amber-500"><Star size={13} fill="currentColor"/>{p.rating.toFixed(1)}</div><p className="mt-2 font-bold">{money(salePrice(p))}</p></div></Link></div>)}</div>}</Shell>}
function WishlistPage({user}:{user: any}){const [products,setProducts]=useState<Product[]>([]);useEffect(()=>{if(user)supabase.from('wishlist_items').select('product:products(*, category:categories(name,slug))').eq('user_id',user.id).then(({data})=>setProducts((data??[]).map((x:any)=>x.product)));},[user]);if(!user)return <AuthPrompt title="Your wishlist is waiting"/>;return <Shell eyebrow="Saved for later" title="Your wishlist"><ProductGrid products={products}/>{!products.length&&<Empty title="Nothing saved yet" text="Tap the heart on anything that catches your eye."/>}</Shell>}
function CartPage({user}:{user:any}){const [items,setItems]=useState<CartItem[]>([]);const load=()=>{if(user)supabase.from('cart_items').select('*, product:products(*)').eq('user_id',user.id).then(({data})=>setItems((data??[]) as CartItem[]))};useEffect(load,[user]);if(!user)return <AuthPrompt title="Your bag is ready when you are"/>;const subtotal=items.reduce((s,i)=>s+salePrice(i.product)*i.quantity,0);const update=async(i:CartItem,q:number)=>{if(q<1)await supabase.from('cart_items').delete().eq('id',i.id);else await supabase.from('cart_items').update({quantity:q}).eq('id',i.id);load();};return <Shell eyebrow="Shopping bag" title="Ready when you are"><div className="grid gap-8 lg:grid-cols-[1fr_360px]">{items.length?<><div className="space-y-3">{items.map(i=><div key={i.id} className="flex gap-4 rounded-2xl bg-white p-4 ring-1 ring-slate-100"><img src={i.product.image_url} className="h-24 w-24 rounded-xl object-cover"/><div className="flex-1"><p className="text-xs text-slate-400">{i.product.brand}</p><h3 className="font-semibold">{i.product.name}</h3><p className="mt-2 font-bold">{money(salePrice(i.product))}</p></div><div className="flex items-center self-center rounded-xl border border-slate-200"><button onClick={()=>update(i,i.quantity-1)} className="px-3 py-2">−</button><span>{i.quantity}</span><button onClick={()=>update(i,i.quantity+1)} className="px-3 py-2">+</button></div></div>)}</div><div className="h-fit rounded-2xl bg-slate-950 p-6 text-white"><p className="text-sm text-slate-400">Order summary</p><div className="mt-5 flex justify-between"><span>Subtotal</span><b>{money(subtotal)}</b></div><div className="mt-3 flex justify-between text-sm text-slate-400"><span>Shipping</span><span>{subtotal>75?'Free':money(8)}</span></div><div className="my-5 border-t border-white/10"/><div className="flex justify-between text-xl font-bold"><span>Total</span><span>{money(subtotal+(subtotal>75?0:8))}</span></div><Link to="/checkout" className="mt-6 block rounded-xl bg-emerald-400 py-3 text-center font-semibold text-slate-950">Continue to checkout</Link></div></>:<Empty title="Your bag is empty" text="Discover something great and it will appear here."/>}</div></Shell>}
function CheckoutPage({user,refreshCounts}:{user: any;refreshCounts:()=>void}){const [items,setItems]=useState<CartItem[]>([]);const [done,setDone]=useState('');useEffect(()=>{if(user)supabase.from('cart_items').select('*, product:products(*)').eq('user_id',user.id).then(({data})=>setItems((data??[]) as CartItem[]))},[user]);if(!user)return <AuthPrompt title="Sign in to checkout"/>;const total=items.reduce((s,i)=>s+salePrice(i.product)*i.quantity,0);const submit=async(e:FormEvent)=>{e.preventDefault();const {data:order,error}=await supabase.from('orders').insert({user_id:user.id,total:total+(total>75?0:8),status:'CONFIRMED',payment_method:'DEMO_CARD',shipping:{}}).select().maybeSingle();if(error||!order)return alert('Could not place order. Please try again.');await supabase.from('order_items').insert(items.map(i=>({order_id:order.id,product_id:i.product_id,quantity:i.quantity,price:salePrice(i.product)})));await Promise.all(items.map(i=>supabase.from('user_interactions').insert({user_id:user.id,product_id:i.product_id,interaction_type:'PURCHASE',weight:5})));await supabase.from('cart_items').delete().eq('user_id',user.id);refreshCounts();setDone(order.id)};if(done)return <Shell title="Order confirmed"><div className="mx-auto max-w-xl rounded-3xl bg-emerald-50 p-10 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-emerald-500 text-white"><Check/></div><h2 className="mt-5 text-2xl font-bold">Your order is on its way.</h2><p className="mt-2 text-slate-600">Thanks for shopping with us. Order #{done.slice(0,8)}</p><Link to="/recommendations" className="mt-6 inline-flex rounded-xl bg-slate-950 px-5 py-3 font-semibold text-white">See what's next</Link></div></Shell>;return <Shell eyebrow="Secure demo checkout" title="Complete your order"><form onSubmit={submit} className="grid gap-8 lg:grid-cols-[1fr_360px]"><div className="rounded-2xl bg-white p-6 ring-1 ring-slate-100"><h2 className="text-xl font-bold">Shipping details</h2><div className="mt-5 grid gap-4 sm:grid-cols-2"><input required placeholder="Full name" className="rounded-xl border p-3"/><input required type="email" placeholder="Email address" className="rounded-xl border p-3"/><input required placeholder="Street address" className="rounded-xl border p-3 sm:col-span-2"/><input required placeholder="City" className="rounded-xl border p-3"/><input required placeholder="Postal code" className="rounded-xl border p-3"/></div><h2 className="mt-8 text-xl font-bold">Payment</h2><div className="mt-4 rounded-xl border-2 border-emerald-500 bg-emerald-50 p-4"><p className="font-semibold">Demo card payment</p><p className="mt-1 text-sm text-slate-500">This is a simulation. No payment is processed.</p></div></div><div className="h-fit rounded-2xl bg-slate-950 p-6 text-white"><h2 className="font-bold">Your total</h2><p className="mt-4 text-3xl font-bold">{money(total+(total>75?0:8))}</p><button className="mt-6 w-full rounded-xl bg-emerald-400 py-3 font-semibold text-slate-950">Place demo order</button></div></form></Shell>}
function AuthPage({mode}:{mode:'login'|'register'}){const nav=useNavigate();const [name,setName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const submit=async(e:FormEvent)=>{e.preventDefault();const result=mode==='login'?await supabase.auth.signInWithPassword({email,password}):await supabase.auth.signUp({email,password,options:{data:{name}}});if(result.error)alert('We could not complete that request. Check your details and try again.');else nav('/')};return <main className="mx-auto flex min-h-[65vh] max-w-md items-center px-4 py-16"><form onSubmit={submit} className="w-full rounded-3xl bg-white p-8 shadow-xl ring-1 ring-slate-100"><div className="mb-8 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-slate-950 text-white"><Sparkles size={20}/></div><h1 className="mt-5 text-2xl font-bold">{mode==='login'?'Welcome back':'Create your account'}</h1><p className="mt-2 text-sm text-slate-500">{mode==='login'?'Your personalized storefront is waiting.':'Join a better way to discover products.'}</p></div>{mode==='register'&&<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" className="mb-3 w-full rounded-xl border p-3"/>}<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Email address" className="mb-3 w-full rounded-xl border p-3"/><input required minLength={6} type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Password" className="w-full rounded-xl border p-3"/><button className="mt-5 w-full rounded-xl bg-slate-950 py-3.5 font-semibold text-white">{mode==='login'?'Sign in':'Create account'}</button><p className="mt-5 text-center text-sm text-slate-500">{mode==='login'?<>New here? <Link className="font-semibold text-emerald-600" to="/register">Create an account</Link></>:<>Already a member? <Link className="font-semibold text-emerald-600" to="/login">Sign in</Link></>}</p></form></main>}
function AccountPage({user}:{user: any}){if(!user)return <AuthPrompt title="Your account, your way"/>;return <Shell eyebrow="Account" title="Welcome back"><div className="grid gap-4 sm:grid-cols-3"><Link to="/orders" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100"><Package className="text-emerald-500"/><h3 className="mt-5 font-bold">Orders</h3><p className="mt-1 text-sm text-slate-500">Track your purchases</p></Link><Link to="/wishlist" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100"><Heart className="text-rose-500"/><h3 className="mt-5 font-bold">Wishlist</h3><p className="mt-1 text-sm text-slate-500">Your saved finds</p></Link><Link to="/recommendations" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100"><Sparkles className="text-amber-500"/><h3 className="mt-5 font-bold">For you</h3><p className="mt-1 text-sm text-slate-500">Your evolving feed</p></Link></div></Shell>}
function OrdersPage({user}:{user:any}) { const [orders,setOrders]=useState<any[]>([]); useEffect(()=>{if(user)supabase.from('orders').select('*').eq('user_id',user.id).order('created_at',{ascending:false}).then(({data})=>setOrders(data??[]));},[user]); if(!user)return <AuthPrompt title="Sign in to view orders"/>; return <Shell eyebrow="Order history" title="Your orders">{orders.length ? <div className="space-y-3">{orders.map(order=><div key={order.id} className="flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-white p-5 ring-1 ring-slate-100"><div><p className="text-xs text-slate-400">Order #{order.id.slice(0,8)}</p><p className="mt-1 font-semibold">{new Date(order.created_at).toLocaleDateString()}</p></div><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">{order.status}</span><p className="font-bold">{money(Number(order.total))}</p></div>)}</div> : <Empty title="No orders yet" text="Your completed purchases will appear here."/>}</Shell>; }
function AdminPage({profile}:{profile:any}){const [stats,setStats]=useState<any>({});useEffect(()=>{if(profile?.role==='ADMIN')Promise.all([supabase.from('products').select('*',{count:'exact',head:true}),supabase.from('orders').select('*',{count:'exact',head:true}),supabase.from('user_interactions').select('*',{count:'exact',head:true}),supabase.from('profiles').select('*',{count:'exact',head:true})]).then(([p,o,i,u])=>setStats({products:p.count,orders:o.count,interactions:i.count,users:u.count}));},[profile]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;return <Shell eyebrow="Admin studio" title="The signals behind the shop" subtitle="A quick view of the catalog, community, and recommendation engine."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[['Products',stats.products,Package],['Orders',stats.orders,ShoppingBag],['Users',stats.users,User],['Interactions',stats.interactions,BarChart3]].map(([label,value,Icon]:any)=><div className="rounded-2xl bg-white p-5 ring-1 ring-slate-100" key={label}><Icon className="text-emerald-500" size={20}/><p className="mt-5 text-sm text-slate-500">{label}</p><p className="mt-1 text-3xl font-bold">{value??'—'}</p></div>)}</div><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Link to="/admin/products" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100 hover:shadow-lg"><Package className="text-emerald-500"/><h3 className="mt-4 font-bold">Manage products</h3><p className="mt-1 text-sm text-slate-500">Add, edit, and remove items</p></Link><Link to="/admin/users" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100 hover:shadow-lg"><User className="text-emerald-500"/><h3 className="mt-4 font-bold">Manage users</h3><p className="mt-1 text-sm text-slate-500">View all registered users</p></Link><Link to="/admin/orders" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100 hover:shadow-lg"><ShoppingBag className="text-emerald-500"/><h3 className="mt-4 font-bold">Manage orders</h3><p className="mt-1 text-sm text-slate-500">View and update order status</p></Link><Link to="/admin/analytics" className="rounded-2xl bg-white p-6 ring-1 ring-slate-100 hover:shadow-lg"><BarChart3 className="text-emerald-500"/><h3 className="mt-4 font-bold">Analytics</h3><p className="mt-1 text-sm text-slate-500">Interaction and recommendation insights</p></Link></div><div className="mt-8 rounded-2xl bg-slate-950 p-8 text-white"><div className="flex items-center gap-3"><TrendingUp className="text-emerald-400"/><h2 className="text-xl font-bold">Hybrid recommendation engine</h2></div><p className="mt-3 max-w-2xl leading-7 text-slate-300">Recommendations blend content similarity (TF-IDF + cosine), collaborative filtering (user-item matrix), popularity scoring, and recency-weighted interactions. Weights: 40% content, 30% collaborative, 20% popularity, 10% recent — all configurable in src/lib/recommendations.ts.</p></div></Shell>}
function AboutPage(){return <Shell eyebrow="Our story" title="A smarter way to shop" subtitle="We built Luma Market to make online shopping feel personal again."><div className="grid gap-8 lg:grid-cols-2"><div className="space-y-4 text-slate-600 leading-7"><p>Luma Market started with a simple idea: every shopper deserves a feed that actually understands them. Instead of generic bestseller lists, we wanted recommendations that learn from what you browse, save, and buy.</p><p>Our recommendation engine runs entirely on our own infrastructure — no external AI APIs, no paid services. It combines four proven approaches: popularity scoring, content-based filtering using TF-IDF and cosine similarity, collaborative filtering across our user base, and a recency-weighted blend of your latest activity.</p><p>The result is a shopping experience that gets better the more you use it. Every product view, wishlist addition, and purchase helps us understand your taste and surface things you'll genuinely love.</p></div><div className="rounded-3xl bg-slate-950 p-8 text-white"><h3 className="text-xl font-bold">What makes us different</h3><div className="mt-6 space-y-4"><div className="flex gap-3"><Sparkles className="text-emerald-400" size={20}/><div><p className="font-semibold">Personalized from day one</p><p className="text-sm text-slate-400">New users get trending picks; returning users get tailored recommendations.</p></div></div><div className="flex gap-3"><TrendingUp className="text-emerald-400" size={20}/><div><p className="font-semibold">Transparent algorithms</p><p className="text-sm text-slate-400">Every recommendation comes with a reason you can understand.</p></div></div><div className="flex gap-3"><Zap className="text-emerald-400" size={20}/><div><p className="font-semibold">No external dependencies</p><p className="text-sm text-slate-400">The entire engine runs locally — no API keys, no paid services.</p></div></div></div></div></div></Shell>;}
function ContactPage(){const [sent,setSent]=useState(false);const submit=(e:FormEvent)=>{e.preventDefault();setSent(true);};return <Shell eyebrow="Get in touch" title="Contact us" subtitle="Questions, feedback, or just want to say hello? We'd love to hear from you.">{sent?<div className="mx-auto max-w-lg rounded-3xl bg-emerald-50 p-10 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-emerald-500 text-white"><Check/></div><h2 className="mt-4 text-xl font-bold">Message sent!</h2><p className="mt-2 text-slate-600">We'll get back to you within 24 hours.</p></div>:<form onSubmit={submit} className="mx-auto max-w-lg space-y-4"><input required placeholder="Your name" className="w-full rounded-xl border border-slate-200 p-3"/><input required type="email" placeholder="Email address" className="w-full rounded-xl border border-slate-200 p-3"/><textarea required placeholder="Your message" className="h-36 w-full resize-none rounded-xl border border-slate-200 p-3"/><button className="w-full rounded-xl bg-slate-950 py-3.5 font-semibold text-white">Send message</button></form>}</Shell>;}
function ForgotPasswordPage(){const [sent,setSent]=useState(false);const submit=async(e:FormEvent)=>{e.preventDefault();setSent(true);};return <main className="mx-auto flex min-h-[65vh] max-w-md items-center px-4 py-16"><div className="w-full rounded-3xl bg-white p-8 shadow-xl ring-1 ring-slate-100"><div className="mb-8 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-slate-950 text-white"><Sparkles size={20}/></div><h1 className="mt-5 text-2xl font-bold">Reset your password</h1><p className="mt-2 text-sm text-slate-500">Enter your email and we'll send you a reset link.</p></div>{sent?<div className="rounded-2xl bg-emerald-50 p-6 text-center text-emerald-800"><p className="font-semibold">If that email is registered, a reset link is on its way.</p></div>:<form onSubmit={submit}><input required type="email" placeholder="Email address" className="mb-3 w-full rounded-xl border p-3"/><button className="w-full rounded-xl bg-slate-950 py-3.5 font-semibold text-white">Send reset link</button></form>}<p className="mt-5 text-center text-sm text-slate-500"><Link className="font-semibold text-emerald-600" to="/login">Back to sign in</Link></p></div></main>;}
function OrderDetailsPage({user}:{user:any}){const {id}=useParams();const [order,setOrder]=useState<any>(null);const [items,setItems]=useState<any[]>([]);useEffect(()=>{if(!id||!user)return;supabase.from('orders').select('*').eq('id',id).eq('user_id',user.id).maybeSingle().then(({data})=>setOrder(data));supabase.from('order_items').select('*, product:products(*)').eq('order_id',id).then(({data})=>setItems(data??[]));},[id,user]);if(!user)return <AuthPrompt title="Sign in to view this order"/>;if(!order)return <Shell title="Loading order..."><div className="h-48 animate-pulse rounded-2xl bg-slate-200"/></Shell>;return <Shell eyebrow="Order details" title={`Order #${order.id.slice(0,8)}`}><div className="grid gap-8 lg:grid-cols-[1fr_320px]"><div className="space-y-3">{items.map((item:any)=><div key={item.id} className="flex gap-4 rounded-2xl bg-white p-4 ring-1 ring-slate-100"><img src={item.product?.image_url} className="h-20 w-20 rounded-xl object-cover"/><div><p className="text-xs text-slate-400">{item.product?.brand}</p><h3 className="font-semibold">{item.product?.name}</h3><p className="mt-1 text-sm text-slate-500">Qty {item.quantity} × {money(Number(item.price))}</p></div><p className="ml-auto font-bold">{money(Number(item.price)*item.quantity)}</p></div>)}</div><div className="h-fit rounded-2xl bg-slate-950 p-6 text-white"><p className="text-sm text-slate-400">Summary</p><div className="mt-4 flex justify-between"><span>Status</span><span className="font-bold text-emerald-400">{order.status}</span></div><div className="mt-3 flex justify-between"><span>Date</span><span>{new Date(order.created_at).toLocaleDateString()}</span></div><div className="mt-3 flex justify-between"><span>Payment</span><span>{order.payment_method}</span></div><div className="my-5 border-t border-white/10"/><div className="flex justify-between text-xl font-bold"><span>Total</span><span>{money(Number(order.total))}</span></div><Link to="/orders" className="mt-6 block rounded-xl border border-white/20 py-3 text-center font-semibold">All orders</Link></div></div></Shell>;}
function AdminProductsPage({profile}:{profile:any}){const [products,setProducts]=useState<Product[]>([]);const load=()=>{supabase.from('products').select('*, category:categories(name,slug)').order('created_at',{ascending:false}).then(({data})=>setProducts((data??[]) as Product[]));};useEffect(()=>{if(profile?.role==='ADMIN')load();},[profile]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;const del=async(id:string)=>{if(!confirm('Delete this product?'))return;await supabase.from('products').delete().eq('id',id);load();};return <Shell eyebrow="Admin" title="Manage products"><div className="mb-6"><Link to="/admin/products/add" className="inline-flex rounded-xl bg-slate-950 px-5 py-3 font-semibold text-white">Add product</Link></div><div className="overflow-x-auto rounded-2xl bg-white ring-1 ring-slate-100"><table className="w-full text-sm"><thead className="border-b text-left text-slate-500"><tr><th className="p-4">Product</th><th className="p-4">Category</th><th className="p-4">Price</th><th className="p-4">Stock</th><th className="p-4">Actions</th></tr></thead><tbody>{products.map(p=><tr key={p.id} className="border-b last:border-0"><td className="p-4"><div className="flex items-center gap-3"><img src={p.image_url} className="h-12 w-12 rounded-lg object-cover"/><span className="font-medium">{p.name}</span></div></td><td className="p-4 text-slate-500">{p.category?.name}</td><td className="p-4">{money(salePrice(p))}</td><td className="p-4">{p.stock}</td><td className="p-4"><div className="flex gap-2"><Link to={`/admin/products/${p.id}/edit`} className="rounded-lg bg-slate-100 px-3 py-1.5 font-medium hover:bg-slate-200">Edit</Link><button onClick={()=>del(p.id)} className="rounded-lg bg-rose-50 px-3 py-1.5 font-medium text-rose-600 hover:bg-rose-100">Delete</button></div></td></tr>)}</tbody></table></div></Shell>;}
function AdminProductFormPage({profile}:{profile:any}){const {id}=useParams();const nav=useNavigate();const [name,setName]=useState('');const [description,setDescription]=useState('');const [price,setPrice]=useState('');const [discount,setDiscount]=useState('');const [brand,setBrand]=useState('');const [image,setImage]=useState('');const [stock,setStock]=useState('');const [category,setCategory]=useState('');const [tags,setTags]=useState('');const [categories,setCategories]=useState<Category[]>([]);useEffect(()=>{supabase.from('categories').select('*').then(({data})=>setCategories(data??[]));if(id){supabase.from('products').select('*').eq('id',id).maybeSingle().then(({data})=>{if(data){setName(data.name);setDescription(data.description??'');setPrice(String(data.price));setDiscount(String(data.discount));setBrand(data.brand??'');setImage(data.image_url??'');setStock(String(data.stock));setCategory(data.category_id??'');setTags((data.tags??[]).join(', '));}});}},[id]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;const submit=async(e:FormEvent)=>{e.preventDefault();const payload={name,description,price:Number(price),discount:Number(discount||0),brand,image_url:image,stock:Number(stock||0),category_id:category,tags:tags.split(',').map(t=>t.trim()).filter(Boolean)};if(id){await supabase.from('products').update({...payload,updated_at:new Date().toISOString()}).eq('id',id);}else{await supabase.from('products').insert(payload);}nav('/admin/products');};return <Shell eyebrow={id?'Edit product':'Add product'} title={id?'Edit product':'Add a new product'}><form onSubmit={submit} className="mx-auto max-w-2xl space-y-4"><input required value={name} onChange={e=>setName(e.target.value)} placeholder="Product name" className="w-full rounded-xl border border-slate-200 p-3"/><textarea required value={description} onChange={e=>setDescription(e.target.value)} placeholder="Description" className="h-28 w-full resize-none rounded-xl border border-slate-200 p-3"/><div className="grid gap-4 sm:grid-cols-2"><input required value={price} onChange={e=>setPrice(e.target.value)} placeholder="Price" type="number" step="0.01" className="rounded-xl border border-slate-200 p-3"/><input value={discount} onChange={e=>setDiscount(e.target.value)} placeholder="Discount %" type="number" className="rounded-xl border border-slate-200 p-3"/></div><div className="grid gap-4 sm:grid-cols-2"><input required value={brand} onChange={e=>setBrand(e.target.value)} placeholder="Brand" className="rounded-xl border border-slate-200 p-3"/><input required value={stock} onChange={e=>setStock(e.target.value)} placeholder="Stock" type="number" className="rounded-xl border border-slate-200 p-3"/></div><input value={image} onChange={e=>setImage(e.target.value)} placeholder="Image URL" className="w-full rounded-xl border border-slate-200 p-3"/><select required value={category} onChange={e=>setCategory(e.target.value)} className="w-full rounded-xl border border-slate-200 p-3"><option value="">Select category</option>{categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select><input value={tags} onChange={e=>setTags(e.target.value)} placeholder="Tags (comma-separated)" className="w-full rounded-xl border border-slate-200 p-3"/><button className="w-full rounded-xl bg-slate-950 py-3.5 font-semibold text-white">{id?'Save changes':'Create product'}</button><Link to="/admin/products" className="block text-center text-sm text-slate-500">Cancel</Link></form></Shell>;}
function AdminUsersPage({profile}:{profile:any}){const [users,setUsers]=useState<any[]>([]);useEffect(()=>{if(profile?.role==='ADMIN')supabase.from('profiles').select('*').order('created_at',{ascending:false}).then(({data})=>setUsers(data??[]));},[profile]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;return <Shell eyebrow="Admin" title="Manage users"><div className="overflow-x-auto rounded-2xl bg-white ring-1 ring-slate-100"><table className="w-full text-sm"><thead className="border-b text-left text-slate-500"><tr><th className="p-4">Name</th><th className="p-4">Role</th><th className="p-4">Joined</th></tr></thead><tbody>{users.map((u:any)=><tr key={u.id} className="border-b last:border-0"><td className="p-4 font-medium">{u.name}</td><td className="p-4"><span className={`rounded-full px-2 py-0.5 text-xs font-bold ${u.role==='ADMIN'?'bg-rose-50 text-rose-600':'bg-emerald-50 text-emerald-700'}`}>{u.role}</span></td><td className="p-4 text-slate-500">{new Date(u.created_at).toLocaleDateString()}</td></tr>)}</tbody></table></div></Shell>;}
function AdminOrdersPage({profile}:{profile:any}){const [orders,setOrders]=useState<any[]>([]);const load=()=>{supabase.from('orders').select('*, profile:profiles(name)').order('created_at',{ascending:false}).then(({data})=>setOrders(data??[]));};useEffect(()=>{if(profile?.role==='ADMIN')load();},[profile]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;const updateStatus=async(id:string,status:string)=>{await supabase.from('orders').update({status}).eq('id',id);load();};return <Shell eyebrow="Admin" title="Manage orders"><div className="overflow-x-auto rounded-2xl bg-white ring-1 ring-slate-100"><table className="w-full text-sm"><thead className="border-b text-left text-slate-500"><tr><th className="p-4">Order</th><th className="p-4">Customer</th><th className="p-4">Total</th><th className="p-4">Status</th><th className="p-4">Update</th></tr></thead><tbody>{orders.map((o:any)=><tr key={o.id} className="border-b last:border-0"><td className="p-4 font-mono text-xs">#{o.id.slice(0,8)}</td><td className="p-4">{o.profile?.name??'—'}</td><td className="p-4 font-bold">{money(Number(o.total))}</td><td className="p-4"><span className="rounded-full bg-emerald-50 px-2 py-0.5 text-xs font-bold text-emerald-700">{o.status}</span></td><td className="p-4"><select defaultValue={o.status} onChange={e=>updateStatus(o.id,e.target.value)} className="rounded-lg border border-slate-200 p-2 text-xs"><option value="PENDING">PENDING</option><option value="CONFIRMED">CONFIRMED</option><option value="SHIPPED">SHIPPED</option><option value="DELIVERED">DELIVERED</option><option value="CANCELLED">CANCELLED</option></select></td></tr>)}</tbody></table></div></Shell>;}
function AdminAnalyticsPage({profile}:{profile:any}){const [stats,setStats]=useState<any>({});useEffect(()=>{if(profile?.role==='ADMIN')(async()=>{const {data:interactions}=await supabase.from('user_interactions').select('*');const typeCounts:Record<string,number>={};(interactions??[]).forEach((i:any)=>{typeCounts[i.interaction_type]=(typeCounts[i.interaction_type]??0)+1;});const {data:products}=await supabase.from('products').select('*, category:categories(name,slug)');const productInteractions:Record<string,number>={};(interactions??[]).forEach((i:any)=>{productInteractions[i.product_id]=(productInteractions[i.product_id]??0)+(INTERACTION_WEIGHTS[i.interaction_type]??1);});const topProducts=(products??[]).map((p:any)=>({p,score:productInteractions[p.id]??0})).sort((a,b)=>b.score-a.score).slice(0,5).map((x:any)=>({name:x.p.name,score:x.score}));setStats({typeCounts,topProducts,total:interactions?.length??0});})();},[profile]);if(profile?.role!=='ADMIN')return <AuthPrompt title="Admin access required"/>;return <Shell eyebrow="Admin" title="Recommendation analytics" subtitle="Interaction distribution and top-performing products."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{Object.entries(stats.typeCounts??{}).map(([type,count])=><div key={type} className="rounded-2xl bg-white p-5 ring-1 ring-slate-100"><p className="text-sm text-slate-500">{type}</p><p className="mt-1 text-3xl font-bold">{String(count)}</p></div>)}</div><div className="mt-8 rounded-2xl bg-white p-6 ring-1 ring-slate-100"><h2 className="text-xl font-bold">Top products by interaction score</h2><div className="mt-5 space-y-3">{(stats.topProducts??[]).map((p:any,i:number)=><div key={i} className="flex items-center gap-4"><span className="grid h-8 w-8 place-items-center rounded-full bg-slate-950 text-sm font-bold text-white">{i+1}</span><span className="flex-1 font-medium">{p.name}</span><div className="h-2 flex-1 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-emerald-500" style={{width:`${Math.min(100,(p.score/(stats.topProducts?.[0]?.score||1))*100)}%`}}/></div><span className="font-bold">{p.score}</span></div>)}</div></div></Shell>;}
function AuthPrompt({title}:{title:string}){return <Shell title={title} subtitle="Sign in to keep your finds, orders, and recommendations together."><Link to="/login" className="inline-flex rounded-xl bg-slate-950 px-5 py-3 font-semibold text-white">Sign in</Link></Shell>}
function Empty({title,text}:{title:string;text:string}){return <div className="rounded-3xl border border-dashed border-slate-300 bg-white px-6 py-16 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-slate-100 text-slate-400"><ShoppingBag size={20}/></div><h3 className="mt-4 font-bold">{title}</h3><p className="mt-1 text-sm text-slate-500">{text}</p></div>}
export default App;
